 * Unit tests for MathUtils.distance(int[], int[])
 */
public class MathUtils_distance_TriageGen2Test {

    private static final double DELTA = 1e-10;



    @Test
    public void testDistance_StandardEuclidean() {
        // 3-4-5 triangle: distance between (0,0) and (3,4) is 5
