package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.distance(int[], int[])
 */
public class MathUtils_distance_TriageGen2Test {

    private static final double DELTA = 1e-10;





    @Test
    public void testDistance_HigherDimensions() {
        // distance between (1, 2, 3) and (4, 5, 6)
        // sqrt((1-4)^2 + (2-5)^2 + (3-6)^2) = sqrt(9 + 9 + 9) = sqrt(27)
        int[] p1 = {1, 2, 3};
        int[] p2 = {4, 5, 6};
        double expected = Math.sqrt(27.0);
        assertEquals(expected, MathUtils.distance(p1, p2), DELTA);
    }










}

